#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# Telnyx setup for the phone Channel: the account, the keys, ngrok, the Voice API
# application, the number and the allowed Callers.
#
#   bash scripts/telnyx-setup.sh        (from the repo root, where .env lives)
#
# The wizard guides, checks and records. The person does every step in the
# Telnyx portal and the ngrok dashboard themselves. The rules it keeps:
#
# - It never buys anything, never starts ngrok and never places a call. All it
#   asks of the Telnyx API are reads (GET), with the API key sent in a header
#   that never appears in a command line.
# - A key or a phone number is typed without echo, kept in ENV_FILE only, and
#   never printed. A phone number is shown by its last four digits.
# - A value already in ENV_FILE is replaced only after the person agrees.
# - A step that is already done is skipped, so a second run changes nothing.
#
# The portal paths, addresses and API fields were checked against Telnyx's and
# ngrok's docs on 2026-11-16. The page each step rests on is named beside it.

STEP_NAMES=("Account" "API key and public key" "ngrok" "Voice API application" "Number" "Allowed Callers")
STEP_LINES=()   # how each step ended, one line each, for the closing report
FAILED=0        # how many steps failed
AGREED=" "      # KEYs the person has agreed to replace in ENV_FILE this run
WHY=""          # why the last check failed, in words for the person

API_KEY_OK=""   # the API key, once Telnyx has accepted it this run
APP_ID=""       # the Voice API application's id, once it is found ready
APP_STATE=""    # what is wrong with the application, when APP_ID is empty
APP_MISSING=0   # 1 when no application has our webhook address at all
NUMBER_STATE="" # what the number check found: "ok ...", "problem ..." or "none N"

PUBLIC_KEY_FORM='^[A-Za-z0-9+/]{43}=$'   # 32 bytes in Base64
BASE_URL_FORM='^https://[A-Za-z0-9]([A-Za-z0-9.-]*[A-Za-z0-9])?(:[0-9]+)?$'
E164_FORM='^\+[1-9][0-9]{6,14}$'

# ── Reading and writing ENV_FILE ──────────────────────────────────────────

# stored KEY prints KEY's value in ENV_FILE, or nothing.
stored() { _existing "$1" || true; }

# has_value KEY: ENV_FILE holds something for KEY, readable by `stored` or not.
has_value() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line
  line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  line="${line#*=}"
  [[ -n "$line" && "$line" != "''" && "$line" != '""' ]]
}

# setting KEY DEFAULT prints KEY from the environment, else from ENV_FILE, else DEFAULT.
setting() {
  local value="${!1:-}"
  if [[ -z "$value" ]]; then value=$(stored "$1"); fi
  printf '%s' "${value:-$2}"
}

agreed() { [[ "$AGREED" == *" $1 "* ]]; }

# may_replace KEY asks before a value already in ENV_FILE is replaced, and
# remembers a yes so that `store` does not ask again.
may_replace() {
  has_value "$1" || return 0
  agreed "$1" && return 0
  confirm "Replace the $1 stored in $ENV_FILE?" || return 1
  AGREED+="$1 "
}

# store KEY VALUE writes KEY to ENV_FILE. It writes nothing when ENV_FILE holds
# that value already, and it never replaces another value unless the person
# agrees. Every value the wizard keeps goes through here.
store() {
  local key="$1" value="$2"
  if [[ -n "$value" && "$(stored "$key")" == "$value" ]]; then return 0; fi
  may_replace "$key" || return 1
  write_env "$key" "$value"
}

# mktemp is what the library's write_env makes its passing copy of ENV_FILE
# with. This one puts that copy in WORK_DIR, which is this run's own and is
# removed however the run ends, and not in the temp directory shared with
# other programs.
mktemp() { command mktemp "$WORK_DIR/env.XXXXXX"; }

# require_ignored_env_file stops the wizard when git would commit ENV_FILE:
# a file inside a repository that git does not ignore (check-ignore says 1).
require_ignored_env_file() {
  local ignored=0
  command -v git >/dev/null 2>&1 || return 0
  git rev-parse --is-inside-work-tree >/dev/null 2>&1 </dev/null || return 0
  git check-ignore -q "$ENV_FILE" >/dev/null 2>&1 </dev/null || ignored=$?
  if [[ "$ignored" -ne 1 ]]; then return 0; fi
  printf '%s is in a git repository and is not git-ignored, so the keys could be committed.\n' "$ENV_FILE" >&2
  printf 'Add it to .gitignore, then run this again.\n' >&2
  exit 1
}

# ── Reading from the Telnyx API ───────────────────────────────────────────

# telnyx_get KEY PATH makes one read from the Telnyx API. The answer's status
# lands in HTTP_STATUS ("000" when Telnyx could not be reached) and its body in
# the file RESPONSE. The key goes to curl on its standard input, so that it is
# in no command line and no file.
telnyx_get() {
  HTTP_STATUS=$(printf 'Authorization: Bearer %s\n' "$1" |
    curl -sS -g --max-time 20 -o "$RESPONSE" -w '%{http_code}' \
      -H 'Accept: application/json' -H @- "$BASE_URL$2" 2>/dev/null) || HTTP_STATUS="000"
}

# trouble says in words why the last telnyx_get was not a 200.
trouble() {
  if [[ "$HTTP_STATUS" == "000" ]]; then printf 'Telnyx could not be reached at %s' "$BASE_URL"
  else printf 'Telnyx answered HTTP %s' "$HTTP_STATUS"; fi
}

# json EXPRESSION [ARG] prints a JavaScript expression's value over the last
# answer (`d`), with ARG as `arg`. It prints nothing for an answer that is not JSON.
json() {
  node -e '
    const [file, expression, arg] = process.argv.slice(1);
    const d = JSON.parse(require("node:fs").readFileSync(file, "utf8"));
    const value = new Function("d", "arg", `return (${expression});`)(d, arg);
    process.stdout.write(String(value ?? ""));
  ' "$RESPONSE" "$@" </dev/null 2>/dev/null || true
}

# ── Reporting ─────────────────────────────────────────────────────────────

# outcome STATUS "detail" records how the current step ended: done, skipped or
# failed. After a failure it waits, so the reason can be read before the next
# step clears the screen.
outcome() {
  local line
  line=$(printf '%-8s %s. %s: %s' "$1" "$_STAGE_INDEX" "${STEP_NAMES[$((_STAGE_INDEX - 1))]}" "$2")
  STEP_LINES+=("$line")
  if [[ "$1" == failed ]]; then
    FAILED=$((FAILED + 1))
    warn "$line"
    if [[ -t 1 ]]; then pause "Press Enter for the next step"; fi
  else
    printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$line"
  fi
}

# run_step FUNCTION opens the next stage under its name and runs it.
run_step() {
  stage "${STEP_NAMES[$_STAGE_INDEX]}"
  "$1"
}

# report closes the wizard with how every step ended. It fails when a step did.
report() {
  local line
  _clear
  printf '\n%s%s  Telnyx setup%s\n\n' "$BOLD" "$BLUE" "$RESET"
  for line in "${STEP_LINES[@]}"; do say "$line"; done
  printf '\n'
  if (( FAILED )); then
    warn "$FAILED step(s) failed. Put right what they name and run this again: finished steps are skipped."
    printf '\n'
    return 1
  fi
  note "To change a stored value, delete its line from $ENV_FILE and run this again."
  printf '\n'
}

# ── Step 1: the account ───────────────────────────────────────────────────
# https://developers.telnyx.com/docs/account-setup/levels-and-capabilities.md
# https://developers.telnyx.com/docs/account-setup/account-upgrade.md
# https://developers.telnyx.com/docs/voice/programmable-voice/l1-accounts-restirctions.md

known_level() {
  case "$1" in pretrial|trial|paid|verified|enterprise|level1|level2) return 0 ;; esac
  return 1
}

# speaks_notice LEVEL: at this level Telnyx still speaks its abuse notice
# before machine speech (the `speak` command the Call ends with is on its list).
speaks_notice() {
  case "$1" in trial|paid|level1) return 0 ;; esac
  return 1
}

notice_at() {
  if [[ "$1" == level1 ]]; then
    printf 'On a Level 1 account Telnyx speaks its abuse notice before machine speech'
  else
    printf 'Until the account is Verified, Telnyx speaks its abuse notice before machine speech'
  fi
}

# quiet_at LEVEL says why no notice is expected. For Level 2 that is read from
# what the docs leave out: they name the notice for Level 1 only.
quiet_at() {
  if [[ "$1" == level2 ]]; then
    printf "Telnyx's docs put its abuse notice on Level 1 accounts only"
  else
    printf 'At this level Telnyx no longer speaks its abuse notice before machine speech'
  fi
}

step_account() {
  local level
  level=$(stored TELNYX_ACCOUNT_LEVEL)
  if known_level "$level" && [[ "$level" != pretrial ]]; then
    if ! speaks_notice "$level"; then
      outcome skipped "level $level is recorded. $(quiet_at "$level")"
      return 0
    fi
    say "The level recorded for the account is $level."
    say "$(notice_at "$level")."
    if ! confirm "Has the account reached a higher level since?"; then
      outcome skipped "level $level is recorded. $(notice_at "$level")"
      return 0
    fi
    AGREED+="TELNYX_ACCOUNT_LEVEL "
  fi

  say "A Call by phone needs a Telnyx account that may hold a Voice API application: Trial at least."
  note "No account yet? Sign up at https://telnyx.com/sign-up, confirm the email and log in first."
  open_url "https://portal.telnyx.com/#/account/account-levels"
  step "The Account Levels page shows the account's level and collects what the next one needs."
  step "Trial: pass the fraud review. Enough for a first Call, from your one verified number, 10 minutes at most."
  step "Paid: a verified mobile number, a service address, two-factor sign-in and a payment by card (the funds)."
  step "Verified: KYC and Telnyx's AI agent evaluation. Only here does Telnyx stop speaking its abuse notice."
  note "An older account has a Verifications page instead: answer level1 or level2."
  note "Go as far as you can now. The level is recorded, and you can run this again after an upgrade."
  TELNYX_ACCOUNT_LEVEL=""
  ask TELNYX_ACCOUNT_LEVEL "Which level does the portal show (pretrial, trial, paid, verified, enterprise, level1, level2)?" || true
  level=$(printf '%s' "$TELNYX_ACCOUNT_LEVEL" | tr 'A-Z' 'a-z' | tr -d ' ')
  case "$level" in l1) level=level1 ;; l2) level=level2 ;; esac

  if ! known_level "$level"; then
    outcome failed "no account level was given: answer pretrial, trial, paid, verified, enterprise, level1 or level2"
  elif [[ "$level" == pretrial ]]; then
    outcome failed "a pretrial account may not have a Voice API application. Pass Telnyx's fraud review to reach Trial"
  elif ! store TELNYX_ACCOUNT_LEVEL "$level"; then
    outcome failed "the level recorded before was kept"
  elif speaks_notice "$level"; then
    outcome done "level $level is recorded. $(notice_at "$level")"
  else
    outcome done "level $level is recorded. $(quiet_at "$level")"
  fi
}

# ── Step 2: the API key and the public key ────────────────────────────────
# https://developers.telnyx.com/docs/development/api-fundamentals/create-api-keys.md
# https://developers.telnyx.com/docs/development/api-fundamentals/first-api-request.md
# https://developers.telnyx.com/docs/development/api-fundamentals/webhooks/receiving-webhooks.md

# check_api_key KEY asks Telnyx for the balance, the read its docs give for
# trying a key. HTTP_STATUS is 200 when the key works.
check_api_key() { telnyx_get "$1" "/v2/balance"; }

# ensure_api_key leaves a key Telnyx accepts in ENV_FILE and in API_KEY_OK, or
# fails with WHY. KEY_NEW is 1 when this run stored it.
ensure_api_key() {
  local key
  API_KEY_OK=""; KEY_NEW=0
  key=$(stored TELNYX_API_KEY)
  if [[ -n "$key" ]]; then
    check_api_key "$key"
    case "$HTTP_STATUS" in
      200) API_KEY_OK="$key"; return 0 ;;
      401|403)
        say "Telnyx does not accept the TELNYX_API_KEY stored in $ENV_FILE (HTTP $HTTP_STATUS)."
        if ! may_replace TELNYX_API_KEY; then
          WHY="Telnyx does not accept the stored TELNYX_API_KEY (HTTP $HTTP_STATUS), and it was kept"
          return 1
        fi ;;
      *) WHY="the stored TELNYX_API_KEY could not be checked: $(trouble)"; return 1 ;;
    esac
  fi

  open_url "https://portal.telnyx.com/#/app/api-keys"
  step "Select Create API Key, give it a label, choose an expiration and create it."
  step "Copy the value straight away: Telnyx shows it once."
  note "A pretrial or trial account may hold one API key at a time."
  for _ in 1 2 3; do
    TELNYX_API_KEY=""
    ask_secret TELNYX_API_KEY "Paste the API key (input is hidden):" || true
    if [[ -z "$TELNYX_API_KEY" ]]; then WHY="no API key was given"; return 1; fi
    check_api_key "$TELNYX_API_KEY"
    case "$HTTP_STATUS" in
      200)
        if ! store TELNYX_API_KEY "$TELNYX_API_KEY"; then WHY="the TELNYX_API_KEY stored before was kept"; return 1; fi
        API_KEY_OK="$TELNYX_API_KEY"; KEY_NEW=1
        return 0 ;;
      401|403) warn "Telnyx does not accept that key (HTTP $HTTP_STATUS). Copy the whole value and try again." ;;
      *)
        # The value is shown once, so it is kept even though it could not be tried.
        if ! store TELNYX_API_KEY "$TELNYX_API_KEY"; then WHY="the TELNYX_API_KEY stored before was kept"; return 1; fi
        WHY="the API key is stored but could not be checked: $(trouble)"
        return 1 ;;
    esac
  done
  WHY="Telnyx did not accept the API key in three tries"
  return 1
}

# ensure_public_key leaves the account's public key in ENV_FILE, or fails with
# WHY. PUBLIC_NEW is 1 when this run stored it.
ensure_public_key() {
  local key
  PUBLIC_NEW=0
  key=$(stored TELNYX_PUBLIC_KEY)
  if [[ "$key" =~ $PUBLIC_KEY_FORM ]]; then return 0; fi
  if [[ -n "$key" ]]; then
    say "The TELNYX_PUBLIC_KEY stored in $ENV_FILE is not a public key (44 Base64 characters, 32 bytes)."
    if ! may_replace TELNYX_PUBLIC_KEY; then
      WHY="the stored TELNYX_PUBLIC_KEY is not a public key, and it was kept"
      return 1
    fi
  fi

  open_url "https://portal.telnyx.com/#/api-keys/public-key"
  step "Copy the public key shown there. Telnyx signs every webhook, and the server checks the signature with it."
  TELNYX_PUBLIC_KEY=""
  ask_secret TELNYX_PUBLIC_KEY "Paste the public key (input is hidden):" || true
  if ! [[ "$TELNYX_PUBLIC_KEY" =~ $PUBLIC_KEY_FORM ]]; then
    WHY="what was pasted is not the public key: it is 44 Base64 characters (32 bytes)"
    return 1
  fi
  if ! store TELNYX_PUBLIC_KEY "$TELNYX_PUBLIC_KEY"; then WHY="the TELNYX_PUBLIC_KEY stored before was kept"; return 1; fi
  PUBLIC_NEW=1
}

step_keys() {
  local funds=""
  if ! ensure_api_key; then outcome failed "$WHY"; return 0; fi
  # The balance is the answer still in RESPONSE whenever the key was accepted.
  if [[ "$(json 'Number(d.data?.available_credit) > 0 ? "yes" : "no"')" == "no" ]]; then
    funds=" The account's available credit is not above zero: add funds before buying a number."
  fi
  if ! ensure_public_key; then outcome failed "$WHY"; return 0; fi
  if (( KEY_NEW || PUBLIC_NEW )); then
    outcome done "Telnyx accepts the API key, and both keys are in $ENV_FILE.$funds"
  else
    outcome skipped "both keys are in $ENV_FILE already, and Telnyx accepts the API key.$funds"
  fi
}

# ── Step 3: ngrok ─────────────────────────────────────────────────────────
# https://ngrok.com/docs/share-localhost/quickstart.md
# https://ngrok.com/docs/universal-gateway/domains.md (dev domains)
# https://developers.telnyx.com/docs/development/development-tools/ngrok-setup.md

# ngrok_has_token: ngrok is connected to an account. The token is looked for
# without being read into the wizard or shown.
ngrok_has_token() {
  local line file
  if [[ -n "${NGROK_AUTHTOKEN:-}" ]]; then return 0; fi
  line=$(ngrok config check </dev/null 2>/dev/null | head -n1) || return 1
  file="${line#Valid configuration file at }"
  [[ "$file" != "$line" && -f "$file" ]] || return 1
  grep -Eq '^[[:space:]]*authtoken:[[:space:]]*[^[:space:]#]' "$file"
}

# tunnel_command URL prints the command that opens the tunnel, with the flag
# the installed ngrok has for a fixed address.
tunnel_command() {
  local port
  port=$(setting PORT 3000)
  if ngrok http --help </dev/null 2>&1 | grep -q -- '--url'; then printf 'ngrok http %s --url %s' "$port" "$1"
  else printf 'ngrok http %s --domain %s' "$port" "${1#https://}"; fi
}

step_ngrok() {
  local url
  if ! command -v ngrok >/dev/null 2>&1; then
    outcome failed "ngrok is not installed. Install it (brew install ngrok, or https://download.ngrok.com)"
    return 0
  fi
  if ! ngrok_has_token; then
    say "ngrok is installed but has no auth token yet."
    open_url "https://dashboard.ngrok.com/get-started/your-authtoken"
    step "Copy the auth token from that page."
    step "In another terminal run:  ngrok config add-authtoken <the token>"
    note "Do not paste the token here: the wizard has no use for it."
    pause "Press Enter when ngrok has its token"
    if ! ngrok_has_token; then
      outcome failed "ngrok has no auth token. Run: ngrok config add-authtoken <the token>"
      return 0
    fi
  fi

  url=$(stored PUBLIC_BASE_URL)
  if [[ "$url" =~ $BASE_URL_FORM ]]; then
    outcome skipped "ngrok has its auth token, and PUBLIC_BASE_URL is $url. Before a Call, run: $(tunnel_command "$url")"
    return 0
  fi
  if [[ -n "$url" ]]; then
    say "The PUBLIC_BASE_URL stored in $ENV_FILE is not an https:// address with nothing after the host."
    if ! may_replace PUBLIC_BASE_URL; then
      outcome failed "the stored PUBLIC_BASE_URL is not an https:// address, and it was kept"
      return 0
    fi
  fi

  say "Telnyx needs one public address that stays the same from run to run."
  open_url "https://dashboard.ngrok.com/domains"
  step "Every ngrok account has one dev domain that never changes, such as your-assigned-name.ngrok-free.dev."
  step "Copy yours from the Domains page."
  PUBLIC_BASE_URL=""
  ask PUBLIC_BASE_URL "The public address (https://<your domain>):" || true
  url=$(printf '%s' "$PUBLIC_BASE_URL" | tr -d ' ')
  url="${url%/}"
  if [[ -n "$url" && "$url" != *"://"* ]]; then url="https://$url"; fi
  if ! [[ "$url" =~ $BASE_URL_FORM ]]; then
    outcome failed "that is not a public address: give https:// and the domain, with nothing after it"
  elif ! store PUBLIC_BASE_URL "$url"; then
    outcome failed "the PUBLIC_BASE_URL stored before was kept"
  else
    # The wizard does not start ngrok. The command goes in the closing report, where it stays on screen.
    outcome done "ngrok has its auth token, and PUBLIC_BASE_URL is $url. Before a Call, run: $(tunnel_command "$url")"
  fi
}

# ── Step 4: the Voice API application ─────────────────────────────────────
# https://developers.telnyx.com/docs/voice/programmable-voice/voice-api-fundamentals.md
# https://developers.telnyx.com/api-reference/call-control-applications/list-call-control-applications.md

# look_for_application WEBHOOK_URL leaves the id of the application that sends
# API v2 webhooks to that address in APP_ID. When there is none, APP_ID is
# empty and APP_STATE says what is wrong.
look_for_application() {
  local found
  APP_ID=""; APP_MISSING=0
  telnyx_get "$API_KEY_OK" '/v2/call_control_applications?page[size]=250'
  if [[ "$HTTP_STATUS" != 200 ]]; then
    APP_STATE="the applications could not be listed: $(trouble)"
    return 0
  fi
  found=$(json '(() => {
    const apps = d.data ?? [];
    const app = apps.find((a) => a.webhook_event_url === arg);
    if (!app) return `none ${apps.length}`;
    const wrong = [];
    if (String(app.webhook_api_version) !== "2") wrong.push(`its Webhook API version is ${app.webhook_api_version}, not 2`);
    if (app.active === false) wrong.push("it is not active");
    return wrong.length ? `problem ${wrong.join(" and ")}` : `ok ${app.id}`;
  })()' "$1")
  case "$found" in
    ok\ *) APP_ID="${found#ok }"; APP_STATE="" ;;
    problem\ *) APP_STATE="the application with the Webhook URL $1 is not ready: ${found#problem }" ;;
    none\ *) APP_MISSING=1; APP_STATE="none of the account's ${found#none } application(s) has the Webhook URL $1" ;;
    *) APP_STATE="Telnyx's list of applications could not be read" ;;
  esac
}

step_application() {
  local url webhook
  url=$(stored PUBLIC_BASE_URL)
  if [[ -z "$API_KEY_OK" ]]; then outcome failed "it needs an API key that Telnyx accepts (step 2)"; return 0; fi
  if ! [[ "$url" =~ $BASE_URL_FORM ]]; then outcome failed "it needs PUBLIC_BASE_URL (step 3)"; return 0; fi
  webhook="$url/telnyx/webhooks"

  look_for_application "$webhook"
  if [[ -n "$APP_ID" ]]; then
    outcome skipped "an application already sends API v2 webhooks to $webhook"
    return 0
  fi
  # Without the list there is nothing to tell the person to put right in the portal.
  if [[ "$HTTP_STATUS" != 200 ]]; then outcome failed "$APP_STATE"; return 0; fi

  open_url "https://portal.telnyx.com"
  step "In the sidebar go to Real-Time Communication > Voice > Programmable Voice."
  if (( APP_MISSING )); then
    step "On the Voice API Applications tab click Create Voice App."
    step "Application name: anything, such as receptionist."
    step "Webhook URL:  $webhook"
    step "Webhook API version: API v2."
    step "Leave the rest as it is and click Create. Go through Inbound, Outbound and Numbers, then click Complete."
  else
    warn "$APP_STATE."
    step "Open that application on the Voice API Applications tab and put it right, then save."
  fi
  pause "Press Enter when the application is saved"

  look_for_application "$webhook"
  if [[ -n "$APP_ID" ]]; then
    outcome done "the application sends API v2 webhooks to $webhook"
  else
    outcome failed "$APP_STATE"
  fi
}

# ── Step 5: the number ────────────────────────────────────────────────────
# https://developers.telnyx.com/docs/numbers/phone-numbers/buy-phone-number.md
# https://developers.telnyx.com/api-reference/phone-number-configurations/list-phone-numbers.md
# https://developers.telnyx.com/docs/account-setup/levels-and-capabilities/trial.md

# look_for_number leaves in NUMBER_STATE what the account's numbers say about
# the application: "ok <last four digits>[ note]" for an active number assigned
# to it, "problem <what>" for an assigned one that is not active, "none <how
# many numbers the account has>" when none is assigned, or nothing when the
# numbers could not be listed (WHY says so).
look_for_number() {
  NUMBER_STATE=""
  telnyx_get "$API_KEY_OK" '/v2/phone_numbers?page[size]=250'
  if [[ "$HTTP_STATUS" != 200 ]]; then WHY="the numbers could not be listed: $(trouble)"; return 0; fi
  NUMBER_STATE=$(json '(() => {
    const all = d.data ?? [];
    const mine = all.filter((n) => n.connection_id === arg);
    const tail = (n) => String(n.phone_number ?? "").replace(/\D/g, "").slice(-4);
    const usLocal = (n) => n.country_iso_alpha2 === "US" && ["local", "longcode"].includes(n.phone_number_type);
    const active = mine.filter((n) => n.status === "active");
    const ready = active.find(usLocal) ?? active[0];
    if (ready) return `ok ${tail(ready)}${usLocal(ready) ? "" : " (it is not a US local number)"}`;
    if (mine.length) return `problem the number ending ${tail(mine[0])} is assigned to the application, but its status is ${mine[0].status}, not active`;
    return `none ${all.length}`;
  })()' "$APP_ID")
  if [[ -z "$NUMBER_STATE" ]]; then WHY="Telnyx's list of numbers could not be read"; fi
}

step_number() {
  if [[ -z "$APP_ID" ]]; then outcome failed "it needs the Voice API application (step 4)"; return 0; fi

  look_for_number
  case "$NUMBER_STATE" in
    ok\ *) outcome skipped "a number ending ${NUMBER_STATE#ok } is active and assigned to the application"; return 0 ;;
    "") outcome failed "$WHY"; return 0 ;;
  esac

  open_url "https://portal.telnyx.com"
  case "$NUMBER_STATE" in
    problem\ *)
      warn "${NUMBER_STATE#problem }."
      step "Look the number up under Real-Time Communication > Numbers and finish what Telnyx asks for it." ;;
    none\ 0)
      say "The account has no number yet. The wizard does not buy one: you place the order."
      step "In the sidebar go to Real-Time Communication > Numbers > Buy Numbers."
      step "Search with Country United States, Features Voice and Number type Local."
      step "Click Add to Cart next to one number, then Place Order."
      note "A trial account may order one number in its lifetime, a local number of the account's own country."
      step "Then assign it: open the Voice API application and select the number in its Numbers settings." ;;
    *)
      say "The account has ${NUMBER_STATE#none } number(s), but none is assigned to the application."
      step "Go to Real-Time Communication > Voice > Programmable Voice and open the application."
      step "In its Numbers settings select the number, then save." ;;
  esac
  pause "Press Enter when the number is assigned to the application"

  look_for_number
  case "$NUMBER_STATE" in
    ok\ *) outcome done "a number ending ${NUMBER_STATE#ok } is active and assigned to the application" ;;
    problem\ *) outcome failed "${NUMBER_STATE#problem }" ;;
    none\ 0) outcome failed "the account has no number" ;;
    none\ *) outcome failed "the account has ${NUMBER_STATE#none } number(s), but none is assigned to the application" ;;
    *) outcome failed "$WHY" ;;
  esac
}

# ── Step 6: the allowed Callers ───────────────────────────────────────────
# https://developers.telnyx.com/docs/account-setup/using-trial-account.md

# callers_ok LIST: every number in the comma-separated LIST is in E.164 form.
callers_ok() {
  local rest="$1," part
  [[ -n "$1" ]] || return 1
  while [[ -n "$rest" ]]; do
    part="${rest%%,*}"; rest="${rest#*,}"
    [[ "$part" =~ $E164_FORM ]] || return 1
  done
}

# callers_shown LIST prints the numbers as they may be shown: last four digits.
callers_shown() {
  local rest="$1," part shown=""
  while [[ -n "$rest" ]]; do
    part="${rest%%,*}"; rest="${rest#*,}"
    shown+="${shown:+, }ending ${part: -4}"
  done
  printf '%s' "$shown"
}

step_allowed_callers() {
  local callers
  callers=$(stored PHONE_ALLOWED_CALLERS)
  if callers_ok "$callers"; then
    outcome skipped "PHONE_ALLOWED_CALLERS is stored ($(callers_shown "$callers"))"
    return 0
  fi
  if [[ -n "$callers" ]]; then
    say "The PHONE_ALLOWED_CALLERS stored in $ENV_FILE is not a list of numbers in E.164 form."
    if ! may_replace PHONE_ALLOWED_CALLERS; then
      outcome failed "the stored PHONE_ALLOWED_CALLERS is not in E.164 form, and it was kept"
      return 0
    fi
  fi

  say "Only the numbers stored here may call the Receptionist. Every other call is rejected unanswered."
  step "Give your own phone number in E.164 form: a plus, the country code and the number, such as +14155550100."
  if [[ "$(stored TELNYX_ACCOUNT_LEVEL)" == trial ]]; then
    note "A trial account only takes calls from its one verified number, so give that one."
    note "It is set at https://portal.telnyx.com/#/numbers/verified-numbers"
  fi
  PHONE_ALLOWED_CALLERS=""
  ask_secret PHONE_ALLOWED_CALLERS "Your number (input is hidden):" || true
  callers=$(printf '%s' "$PHONE_ALLOWED_CALLERS" | tr -d ' ')
  if [[ -z "$callers" ]]; then
    outcome skipped "no number was given, so any Caller may call. Run this again to store one"
  elif ! callers_ok "$callers"; then
    outcome failed "that is not a phone number in E.164 form, such as +14155550100"
  elif ! store PHONE_ALLOWED_CALLERS "$callers"; then
    outcome failed "the PHONE_ALLOWED_CALLERS stored before was kept"
  else
    outcome done "PHONE_ALLOWED_CALLERS is stored ($(callers_shown "$callers"))"
  fi
}

# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=${#STEP_NAMES[@]}

local tool
for tool in curl node; do
  if ! command -v "$tool" >/dev/null 2>&1; then
    printf 'The wizard needs %s, which was not found.\n' "$tool" >&2
    exit 1
  fi
done
require_ignored_env_file

# The API's address comes from where the phone program will read it. A key is
# only ever sent over https, or to a stand-in on this machine.
BASE_URL=$(setting TELNYX_BASE_URL "https://api.telnyx.com")
BASE_URL="${BASE_URL%/}"
case "$BASE_URL" in
  https://*|http://127.0.0.1:*|http://localhost:*) ;;
  *) printf 'TELNYX_BASE_URL must be an https:// address, so the wizard stops here.\n' >&2; exit 1 ;;
esac

# Working files live in a directory of this run's own, removed however it ends.
WORK_DIR=$(command mktemp -d "${TMPDIR:-/tmp}/telnyx-setup.XXXXXX")
RESPONSE="$WORK_DIR/response.json"
trap 'rm -rf "$WORK_DIR"' EXIT
trap 'exit 130' INT

banner "Telnyx setup for the phone Channel"

run_step step_account
run_step step_keys
run_step step_ngrok
run_step step_application
run_step step_number
run_step step_allowed_callers

report
}

run_wizard "$@"; exit
